"""Shot plan for scenes 2 (rest) - 8 of the 401(k) match episode (the first 53 s are the approved pilot, unchanged).
Each shot names the exact script words it covers (they must tile the narration in order). Types: CA = Maya character action,
REN = Ren host cutaway (genuine library clip, Ren left, graphics right), G = code graphic, STILL = story still. Caps: REN 5.5, STILL 2.5, G 3.5."""
import full_ui as F
import pilot_ui as U

SPEC = []
def add(**k): SPEC.append(k)
def CA(id, sec, ph, poses, cam="m", cards=(), plate="O1"): add(id=id, type="CHARACTER_ACTION", sec=sec, phrase=ph, kind="maya", poses=poses, cam=cam, cards=list(cards), plate=plate)
def REN(id, sec, ph, panel, clip=None): add(id=id, type="REN_ANIMATED", sec=sec, phrase=ph, kind="ren", panel=panel, clip=clip)
def G(id, sec, ph, panel, bg="O1", s=None): add(id=id, type="GRAPHIC", sec=sec, phrase=ph, kind="graphic", panel=panel, bg=bg, s=s)
def STILL(id, sec, ph, image, caption=None): add(id=id, type="STORY_STILL", sec=sec, phrase=ph, kind="still", image=image, caption=caption)
def at(fn, x, y, t0=0.2): return dict(fn=fn, x=x, y=y, t0=t0)

# poses (office stool sheet / receipt sheet / drawer sheet)
S1, S2, S3, S4, S5, S6 = (f"stool_0{i}" for i in range(1, 7))
R1, R2, R3, R4, R5, R6 = (f"receipt_laptop_0{i}" for i in range(1, 7))

# ---- scene 2 (rest): the HR message and Alex --------------------------------------------------------------------------------
CA("N01", "P3", "So how did she end up staring at that number?", [(0, R6), (1.2, S5)])
CA("N02", "P3", "It started earlier that week, with a message from HR:", [(0, S5), (1.0, R4)], cards=[at(lambda t: F.notif_card(), 1160, 120, 0.7)])
G("N03", "P3", "Review your retirement contributions.", lambda t: F.note_card("HR message", ["Review your retirement contributions"], 0, sub="Earlier that week"))
CA("N04", "P3", "She nearly deletes it.", [(0, R4), (0.5, R5), (1.0, R4)], cards=[at(lambda t: F.delete_card(U.clamp(1 - abs(t - 0.6) / 0.5)), 1160, 120, 0.0)])
STILL("N05", "P3", "Then Alex, a colleague, stops by her desk", "D_alex_laptop")
CA("N06", "P3", "and points to a line she's never read:", [(0, S5), (0.9, R4)])
G("N07", "P3", "Employer match: one hundred percent,", lambda t: F.note_card("Plan document", ["Employer match: 100%"], 0, sub="Illustrative example"))
G("N08", "P3", "up to four percent of eligible pay.", lambda t: F.note_card("Plan document", ["Employer match: 100% up to 4% of eligible pay"], 0, sub="Illustrative example"))

# ---- scene 3: the match, Ren left and the two-stream diagram right ------------------------------------------------------------
TS = lambda n: (lambda t: F.two_stream(n, t))
REN("M01", "S3", "So what does that mean?", TS(0))
REN("M02", "S3", "It means that in this example, for every dollar Maya contributes,", TS(1))
REN("M03", "S3", "her company adds a dollar, until she contributes four percent of her salary.", TS(3))
REN("M04", "S3", "On sixty thousand dollars, four percent is twenty-four hundred a year.", TS(4))
G("M05", "S3", "That's two hundred dollars per month from Maya,", lambda t: F.stat_card("From Maya", "$200 / month", tag="Illustrative example"))
G("M06", "S3", "and up to another two hundred from her employer.", lambda t: F.stat_card("From her employer", "up to $200 / month", tag="Illustrative example"))
CA("M07", "S3", "But Maya's been putting in two percent.", [(0, S1), (1.0, S2)], cards=[at(lambda t: F.stat_card("Maya puts in", "2%", w=640), 1200, 150, 0.3)])
REN("M08", "S3", "That's twelve hundred a year from her, with twelve hundred matched by work.", TS(6))
REN("M09", "S3", "She hasn't been getting nothing.", TS(6))
REN("M10", "S3", "She's been getting half the match she could receive.", TS(7))
G("M11", "S3", "The missing half is another twelve hundred dollars a year.", lambda t: F.stat_card("Missing half", "$1,200 / year", tag="Illustrative example"))
G("M12", "S3", "That's one hundred a month of employer money,", lambda t: F.stat_card("Employer money", "$100 / month", tag="Illustrative example"))
REN("M13", "S3", "without asking for a raise or working an extra shift.", TS(9))
REN("M14", "S3", "The catch is that Maya has to put in her own extra hundred a month too,", TS(10))
CA("M15", "S3", "and qualify under her plan.", [(0, R6), (0.8, S6)])

# ---- scene 4: cost, tax treatment, what the match is ---------------------------------------------------------------------------
CA("T01", "S4", "Maya's first thought is entirely reasonable:", [(0, R6), (1.0, S6)])
CA("T02", "S4", "I can't just find another hundred dollars every month.", [(0, S6), (1.2, R2)], cards=[at(lambda t: F.chips(["Rent due", "Groceries", "Phone bill"], w=640), 1220, 150, 0.2)])
CA("T03", "S4", "Rent doesn't disappear because a spreadsheet looks exciting.", [(0, R2), (1.6, R1)], cards=[at(lambda t: F.chips(["Rent due"], 0, w=640), 1220, 150, 0.0)])
G("T04", "S4", "And this is where some videos would shout, It's free money, do it now!", lambda t: F.bubble("It's free money, do it now!"))
G("T05", "S4", "But it's not quite that simple.", lambda t: F.bubble("It's free money, do it now!", strike=U.ease(t / 1.2)))
CA("T06", "S4", "To unlock the extra match,", [(0, R1), (0.9, S5)])
G("T07", "S4", "Maya would contribute an extra hundred dollars a month from her gross salary.", lambda t: F.stat_card("Extra from her gross salary", "+$100 / month", tag="Illustrative example"))
G("T08", "S4", "If she uses traditional pre-tax contributions,", lambda t: F.outcomes(1))
G("T09", "S4", "the reduction in her take-home pay may be less than a hundred,", lambda t: F.outcomes(2))
CA("T10", "S4", "because her taxable income changes.", [(0, S5), (1.2, R4)])
G("T11", "S4", "If she uses Roth contributions, there's no upfront tax break,", lambda t: F.outcomes(3))
G("T12", "S4", "so her take-home pay falls by the full hundred.", lambda t: F.outcomes(4))
CA("T13", "S4", "And no, an employer match is not cash she can spend next weekend.", [(0, R2), (1.5, R3)], cards=[at(lambda t: F.stat_card("Not spendable next weekend", "$0 today", w=700, tone="red"), 1180, 130, 0.5)])
REN("T14", "S4", "It's money in a retirement account,", lambda t: F.chips(["401(k) account"], 0, w=700))
REN("T15", "S4", "invested under her plan's options, with rules about when she can access it.", lambda t: F.chips(["Plan investment options", "Rules for access"], None, w=760))

# ---- scene 5: the budget check and the contribution page ----------------------------------------------------------------------
CA("B01", "S5", "Now Maya has a choice, not an order.", [(0, S6), (1.2, R6)])
CA("B02", "S5", "If she's struggling to cover necessities,", [(0, R6), (1.0, R2)])
CA("B03", "S5", "or she's carrying expensive debt,", [(0, R2), (0.9, R3)])
CA("B04", "S5", "she shouldn't pretend those problems don't exist.", [(0, R3), (1.4, S6)])
CA("B05", "S5", "But she checks her budget instead of guessing.", [(0, R1), (1.2, S5)], cards=[at(lambda t: F.budget(0), 1060, 120, 0.4)])
G("B06", "S5", "The subscription was twelve dollars.", lambda t: F.budget(1))
G("B07", "S5", "A delivery habit she'd already wanted to cut is another forty.", lambda t: F.budget(2))
G("B08", "S5", "A few unused app plans", lambda t: F.budget(2))
G("B09", "S5", "and a gym membership she never visits cover the other forty-eight.", lambda t: F.budget(3))
G("B10", "S5", "That adds up to a hundred dollars a month.", lambda t: F.budget(4))
CA("B11", "S5", "Even if her take-home pay fell by the full hundred,", [(0, S5), (1.4, R6)])
CA("B12", "S5", "she could cover it without draining her emergency savings.", [(0, R6), (1.5, S6)])
G("B13", "S5", "She opens the four-oh-one-k contribution page,", lambda t: F.contrib_ui(2))
G("B14", "S5", "changes two percent to four,", lambda t: F.contrib_ui(2, U.clamp(t / 1.4)))
G("B15", "S5", "then pauses before pressing save.", lambda t: F.contrib_ui(4, 1.0, U.clamp(0.5 + 0.5 * __import__("math").sin(t * 5))))
CA("B16", "S5", "Because there is one more line she needs to read.", [(0, R5), (1.0, R4)])

# ---- scene 6: vesting and the plan document --------------------------------------------------------------------------------------
G("V01", "S6", "Vesting.", lambda t: F.stat_card("Today's word", "Vesting"))
CA("V02", "S6", "It's an unglamorous word that can make a very real difference.", [(0, R6), (1.5, R1)])
G("V03", "S6", "Maya always owns the money she contributes herself.", lambda t: F.stat_card("What Maya contributes", "always hers", tone="gold"))
G("V04", "S6", "Her employer's money may become fully hers immediately,", lambda t: F.vesting(1))
G("V05", "S6", "or only after she meets her plan's service requirements.", lambda t: F.vesting(2))
CA("V06", "S6", "Different employers use different rules.", [(0, R1), (1.1, R3)])
G("V07", "S6", "The match formula can vary, too.", lambda t: F.note_card("Match formula", ["100% up to 4%", "50 cents per $1", "No match"], 0, sub="Examples"))
G("V08", "S6", "Some match fifty cents per dollar.", lambda t: F.note_card("Match formula", ["100% up to 4%", "50 cents per $1", "No match"], 1, sub="Examples"))
G("V09", "S6", "Some set different percentages.", lambda t: F.note_card("Match formula", ["100% up to 4%", "50 cents per $1", "Different percentages"], 2, sub="Examples"))
G("V10", "S6", "Some don't offer a match at all.", lambda t: F.note_card("Match formula", ["100% up to 4%", "50 cents per $1", "No match at all"], 2, sub="Examples"))
G("V11", "S6", "Eligibility dates, pay-period calculations", lambda t: F.chips(["Eligibility dates", "Pay-period calculations", "Year-end true-ups"], 0, title="Details that matter"))
G("V12", "S6", "and year-end true-ups can all matter.", lambda t: F.chips(["Eligibility dates", "Pay-period calculations", "Year-end true-ups"], 2, title="Details that matter"))
G("V13", "S6", "A true-up tops up the match", lambda t: F.trueup(0))
G("V14", "S6", "if her contributions were uneven across the year.", lambda t: F.trueup(1))
CA("V15", "S6", "That's why copying a percentage from a stranger online isn't a plan.", [(0, R2), (1.8, R3)], cards=[at(lambda t: F.stat_card("A stranger's percentage", "not a plan", w=700, tone="red"), 1180, 130, 0.5)])
CA("V16", "S6", "Maya finds the Summary Plan Description", [(0, R1), (1.1, S5)], cards=[at(lambda t: F.note_card("Summary Plan Description", ["Employer contributions"], None, w=700), 1180, 130, 0.4)])
CA("V17", "S6", "and checks what her employer actually promises.", [(0, S5), (1.2, R4)], cards=[at(lambda t: F.note_card("Summary Plan Description", ["Employer contributions"], 0, w=700), 1180, 130, 0.0)])
G("V18", "S6", "In this example, employer contributions", lambda t: F.vesting(2))
G("V19", "S6", "vest after three years of service,", lambda t: F.vesting(3))
G("V20", "S6", "and she's already reached that mark.", lambda t: F.vesting(4))

# ---- scene 7: save, evidence -----------------------------------------------------------------------------------------------------------
CA("E01", "S7", "Satisfied with what she's read, Maya presses save.", [(0, R4), (1.2, R5)], cards=[at(lambda t: F.contrib_ui(4, 1.0, 0.0, saved=t > 1.4, w=760, h=470), 1100, 120, 0.2)])
CA("E02", "S7", "Then she does three things.", [(0, R5), (0.8, S6)])
G("E03", "S7", "First, she keeps the confirmation page, so there's a record of what she chose and when.", lambda t: F.note_card("Confirmation page", ["Contribution: 4%", "Saved: a record of what and when"], 0))
CA("E04", "S7", "Second, once the change reaches payroll,", [(0, S6), (1.2, R1)])
G("E05", "S7", "she checks her next pay stub to see the new contribution.", lambda t: F.paystub(1))
CA("E06", "S7", "Third, she checks her four-oh-one-k statement", [(0, R1), (1.2, S5)])
G("E07", "S7", "to see the employer match arriving beside it.", lambda t: F.statement(1))
G("E08", "S7", "A few weeks later, it all appears.", lambda t: F.streams(t))
G("E09", "S7", "Her paycheck is a little smaller.", lambda t: F.paystub(2))
G("E10", "S7", "Her retirement deposit is bigger.", lambda t: F.statement(2))
CA("E11", "S7", "And she's no longer wondering whether she missed a box in a benefits form.", [(0, R6), (1.5, S6), (3.0, S2)])
REN("E12", "S7", "She has evidence.", lambda t: F.note_card("Evidence", ["Confirmation page", "Pay stub", "Statement"], 2, w=760))

# ---- scene 8: the cost of waiting, three actions, outro ------------------------------------------------------------------------------
CA("C01", "S8", "Here's the part Maya wishes she'd understood earlier.", [(0, S6), (1.5, R6)])
G("C02", "S8", "The one hundred dollars a month she wasn't getting", lambda t: F.stat_card("Not received", "$100 / month", tag="Illustrative example"))
G("C03", "S8", "wasn't a guaranteed investment return.", lambda t: F.stat_card("Guaranteed investment return", "no", strike=True, tone="red"))
G("C04", "S8", "It wasn't a gift card.", lambda t: F.stat_card("Gift card", "no", strike=True, tone="red"))
G("C05", "S8", "It was an employer contribution she was eligible to unlock", lambda t: F.note_card("What it was", ["Employer contribution"], 0, sub="Eligible to unlock"))
G("C06", "S8", "under this example plan.", lambda t: F.note_card("What it was", ["Employer contribution"], 0, sub="Under this example plan"))
G("C07", "S8", "In the three years she's already worked there,", lambda t: F.calendar(3, "Years already worked", 0))
G("C08", "S8", "that's about thirty-six hundred dollars left unclaimed.", lambda t: F.stat_card("Left unclaimed so far", "$3,600", tag="3 years x $1,200"))
G("C09", "S8", "Leave it unclaimed for ten more years,", lambda t: F.calendar(10, "Ten more years", 0))
G("C10", "S8", "and that's twelve thousand dollars of employer contributions alone,", lambda t: F.stat_card("Ten more years", "$12,000", tag="10 years x $1,200"))
G("C11", "S8", "before considering any investment growth,", lambda t: F.chips(["Investment growth", "Changes in salary", "Changes to the plan"], 0, title="Not included"))
G("C12", "S8", "changes in salary, or changes to the plan.", lambda t: F.chips(["Investment growth", "Changes in salary", "Changes to the plan"], 2, title="Not included"))
G("C13", "S8", "Markets can rise or fall.", lambda t: F.stat_card("Markets", "up or down"))
REN("C14", "S8", "The match is still worth understanding.", lambda t: F.stat_card("The match", "worth understanding", w=760, tone="gold"))
REN("C15", "S8", "So before you spend another evening hunting for tiny savings,", lambda t: F.chips(["Another evening of tiny savings?"], 0, w=800))
REN("C16", "S8", "give your retirement benefits ten minutes.", lambda t: F.stat_card("Your retirement benefits", "10 minutes", w=760))
REN("C17", "S8", "Look for the match formula,", lambda t: F.chips(["1  Match formula", "2  Vesting rules", "3  Contribution level"], 0, w=760, title="Three things to check"))
REN("C18", "S8", "the vesting rules,", lambda t: F.chips(["1  Match formula", "2  Vesting rules", "3  Contribution level"], 1, w=760, title="Three things to check"))
REN("C19", "S8", "and the contribution level that actually earns it.", lambda t: F.chips(["1  Match formula", "2  Vesting rules", "3  Contribution level"], 2, w=760, title="Three things to check"))
REN("C20", "S8", "I'm Ren.", lambda t: F.chips(["Ren"], 0, w=420), clip="ren_wave_hello")
REN("C21", "S8", "And sometimes the next useful money move isn't earning more.", lambda t: F.stat_card("The next useful money move", "isn't earning more", w=800))
REN("C22", "S8", "It's noticing what's already on the table.", lambda t: F.stat_card("What's already on the table", "the match", w=800, tone="gold"))
REN("C23", "S8", "Check out the Money Leak Audit Workbook in the description.", lambda t: F.cta(), clip="ren_point_camera")
REN("C24", "S8", "Educational only, not financial advice.", lambda t: F.stat_card("Educational only", "not financial advice", w=800, tone="cream"))
